/**
 * Hermes' official skill library (hermes/optional-skills, 141 skills) and the skills it bundles
 * into every agent (hermes/skills, 44), as McBot's list of them:
 * read with the engine's own reader (engine/skills.ts listLibrary), so the browser demo shows the
 * whole library and starter agents can only name skills Hermes really ships (test/library.test.ts).
 * `npm test` fails when the generated file is stale: run `npm run engine:library` after a Hermes sync.
 *
 *   npx tsx scripts/hermes-library.ts     write src/contracts/library.generated.ts
 *   renderLibrary()                        the file's text (used by the test)
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { listLibrary, listSkills } from "../engine/skills";

const ROOT = join(import.meta.dirname ?? __dirname, "..");
export const OUT = join(ROOT, "src/contracts/library.generated.ts");

/** First sentence, one line, at most 140 characters. */
const oneLine = (s: string) => {
  const first = s.replace(/\s+/g, " ").trim().split(/(?<=\.)\s/)[0]!;
  return first.length > 140 ? `${first.slice(0, 139).trimEnd()}…` : first;
};

export function renderLibrary(): string {
  const rows = listLibrary(join(ROOT, "hermes"))
    .sort((a, b) => a.id.localeCompare(b.id))
    .map((s) => `  ${JSON.stringify({ id: s.id, name: s.name, category: s.category, description: oneLine(s.description), tags: s.tags.slice(0, 4) })},`);
  const bundled = listSkills(join(ROOT, "hermes", "skills"))
    .sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
    .map((s) => `  ${JSON.stringify({ name: s.name, category: s.category, description: oneLine(s.description) })},`);
  return [
    "// Generated by scripts/hermes-library.ts from hermes/optional-skills and hermes/skills (**/SKILL.md). Do not edit.",
    "// Run `npm run engine:library` after a Hermes sync; `npm test` fails while this file is stale.",
    "import type { LibrarySkill } from \"./api\";",
    "",
    "export const LIBRARY: readonly LibrarySkill[] = [",
    ...rows,
    "];",
    "",
    "/** The skills Hermes seeds into every agent (unless its built-in skills are off). */",
    "export const BUNDLED: readonly { name: string; category: string; description: string }[] = [",
    ...bundled,
    "];",
    "",
  ].join("\n");
}

if (process.argv[1] && /hermes-library\.ts$/.test(process.argv[1])) {
  writeFileSync(OUT, renderLibrary());
  console.log(`wrote ${OUT}`);
}
